"""Parse Adobe Illustrator 8 art (from AI private data) into vector paths."""
import re, sys, json

NUM = re.compile(rb'[-+]?[0-9]*\.?[0-9]+(?:[eE][-+]?[0-9]+)?')

def tokenize(data):
    i, n = 0, len(data)
    while i < n:
        ch = data[i:i+1]
        if ch in b' \t\r\n':
            i += 1; continue
        if ch == b'%':                       # comment to EOL
            j = data.find(b'\n', i)
            i = n if j < 0 else j + 1
            continue
        if ch == b'(':                       # PostScript string
            depth, j = 1, i + 1
            while j < n and depth:
                c = data[j:j+1]
                if c == b'\\': j += 2; continue
                if c == b'(': depth += 1
                elif c == b')': depth -= 1
                j += 1
            yield ('str', data[i+1:j-1]); i = j; continue
        if ch == b'[' or ch == b']':
            yield ('op', ch.decode()); i += 1; continue
        if ch == b'/':
            m = re.match(rb'/[^\s/()\[\]<>]*', data[i:])
            yield ('name', m.group().decode('latin1')); i += m.end(); continue
        m = NUM.match(data, i)
        if m and m.end() > i:
            # a number must not be a prefix of an identifier
            yield ('num', float(m.group())); i = m.end(); continue
        m = re.match(rb'[A-Za-z*][A-Za-z0-9*_]*', data[i:])
        if m:
            yield ('op', m.group().decode('latin1')); i += m.end(); continue
        i += 1

def rgb(v):
    return '#%02X%02X%02X' % tuple(max(0, min(255, round(c * 255))) for c in v)

def parse(data):
    st = []                      # number stack
    paths = []                   # finished painted paths
    cur = []                     # list of subpaths; each is list of segment strings
    sub = None
    cx = cy = 0.0
    fill = '#000000'
    stroke = '#000000'
    depth = 0

    def flush(paint):
        nonlocal cur, sub
        if sub: cur.append(sub)
        if cur and paint:
            d = ' '.join(' '.join(s) for s in cur)
            paths.append({'d': d, 'fill': fill, 'stroke': stroke,
                          'paint': paint, 'group': depth})
        cur, sub = [], None

    for kind, val in tokenize(data):
        if kind == 'num':
            st.append(val); continue
        if kind != 'op':
            st.clear(); continue
        o = val
        try:
            if o == 'm':
                if sub: cur.append(sub)
                cx, cy = st[-2], st[-1]
                sub = ['M %g %g' % (cx, -cy)]
            elif o in ('l', 'L'):
                cx, cy = st[-2], st[-1]
                sub.append('L %g %g' % (cx, -cy))
            elif o in ('c', 'C'):
                x1, y1, x2, y2, x3, y3 = st[-6:]
                sub.append('C %g %g %g %g %g %g' % (x1, -y1, x2, -y2, x3, -y3))
                cx, cy = x3, y3
            elif o in ('v', 'V'):           # first control point == current point
                x2, y2, x3, y3 = st[-4:]
                sub.append('C %g %g %g %g %g %g' % (cx, -cy, x2, -y2, x3, -y3))
                cx, cy = x3, y3
            elif o in ('y', 'Y'):           # second control point == end point
                x1, y1, x3, y3 = st[-4:]
                sub.append('C %g %g %g %g %g %g' % (x1, -y1, x3, -y3, x3, -y3))
                cx, cy = x3, y3
            elif o in ('f', 'F'):  flush('fill')
            elif o in ('s', 'S'):  flush('stroke')
            elif o in ('b', 'B'):  flush('both')
            elif o in ('n', 'N'):  flush(None)
            elif o == 'Xa':        fill = rgb(st[-3:])
            elif o == 'XA':        stroke = rgb(st[-3:])
            elif o == 'u':         depth += 1
            elif o == 'U':         depth -= 1
        except (IndexError, TypeError):
            pass
        st.clear()
    return paths

def bbox(d):
    pts = [float(x) for x in re.findall(r'-?[0-9.]+(?:e-?[0-9]+)?', d)]
    xs, ys = pts[0::2], pts[1::2]
    return min(xs), min(ys), max(xs), max(ys)

if __name__ == '__main__':
    paths = parse(open(sys.argv[1], 'rb').read())
    fills = [p for p in paths if p['paint'] in ('fill', 'both')]
    print(f'{len(paths)} painted paths, {len(fills)} filled', file=sys.stderr)
    for i, p in enumerate(fills):
        x0, y0, x1, y1 = bbox(p['d'])
        subs = p['d'].count('M')
        print(f'{i:3d} fill={p["fill"]} grp={p["group"]} subpaths={subs:3d} '
              f'bbox=[{x0:9.2f} {y0:9.2f} {x1:9.2f} {y1:9.2f}] '
              f'w={x1-x0:8.2f} h={y1-y0:7.2f}', file=sys.stderr)
    json.dump(fills, open('fills.json', 'w'))
